// Meta css start from here 
  @import url('https://fonts.googleapis.com/css2?family=DM+Serif+Text&family=Inter:wght@400;700&display=swap');
body{
     font-family: 'Inter', sans-serif !important;
}
span,p,a {
 font-family: 'Inter', sans-serif !important;   
}
h1,h2,h3,h4,h5,h6{
     font-family: 'DM Serif Text', serif !important;
}
.halo-middleHeader .navUser-action.cartDesktop .countPill {
    background-color: #0004FF !important;
}
// product listing
.m-product{
    padding-bottom:10px !important;
     box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}
.m-product .card-wishlist,.m-product .card-rating ,.m-product .card-option{
    display: none !important;
}
.m-product .card-action{
    width:100% !important;
    margin:0px !important;
    border:2px solid black !important;
    background-color: transparent;
    color:black;
}
.m-product-title{
    font-size: 15px !important;
    text-align: center;
    font-weight: 700 !important;
    color:black !important;
}
.m-price{
    justify-content: center !important;
}
.m-price .price-section{
    font-size: 16px !important;
    color: #1D6448 !important;
}
.m-dilivery{
    margin: 10px auto;
    display: flex;
    gap:8px;
    align-items: center;
    justify-content: center;
}
.m-dilivery span{
    font-size:12px;
}
.m-prduct-detail{
    font-size: 30px;
   font-family: 'DM Serif Text', serif !important;
   color:black;
   font-weight: 400;
}

.productView-info-item span.productView-info-name{
    min-width: 3px !important;
    font-size: 18px;
}
.productView-info-item span.productView-info-value{
    font-style:normal !important;
} 
.m-custom-box{
    box-shadow:
        -5px -5px 15px rgba(0, 0, 0, 0.1),
         5px -5px 15px rgba(0, 0, 0, 0.1); 
         padding:35px !important;
}
// warranty css in product view: 
.warranty-selector {

  max-width: 500px;
}

.title {
  margin-bottom: 12px;
  font-size: 14px;
}

.title strong {
  font-weight: 700;
}

.title span {
  font-weight: 400;
}

.options {
  display: flex;
  align-items: center;
  gap: 12px;
}

.option {
  border: 2px solid #ccc;
  padding: 12px 16px;
flex:2;
line-height: 1.2;
  cursor: pointer;
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-width: 200px;
  transition: all 0.3s ease;
}

.m-label{
    display: flex;
    flex-direction: column;
}
.m-label strong {
  font-size: 14px;
  font-weight: 700;
}

.m-label span {
  font-size: 14px;
  font-weight: 400;
}

.option.selected {
  border-image: linear-gradient(to right, #9D34B4, #000000) 1;
}

.option .tick {
  display: none;
 
}

.option.selected .tick {
  display: block;
}

.help-container {
  position: relative;
}

.help {
  color: blue;
  font-size: 20px;
  cursor: pointer;
}

.tooltip {
  display: none;
  position: absolute;
  top: 30px;
  left: 0px;
  background-color: #fff;
  border: 1px solid #ccc;
  padding: 8px;
  border-radius: 6px;
  font-size: 13px;
  width: 240px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
  z-index: 10;
}

.help-container:hover .tooltip {
  display: block;
}
.productView-price .price{
    margin-top:10px !important;
    font-size: 35px !important;
    font-weight: 700 !important;
    color: #1D6448 !important;
}
.m-features {
  display: flex;
  justify-content: space-around;
  background-color: #f2f2f2;
  padding: 20px 0;
  gap: 20px;
  flex-wrap: wrap;
  text-align: center;
}

.m-feature-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 120px;
  font-size: 14px;
  color: #000;
}

.m-icon {
  margin-bottom: 8px;
}


// media
@media (min-width: 1024px){
    .pc-nav-center{
        display: flex;
    justify-content: space-around;
    align-items: center;
    }
    .text{
        color:white !important;
    }
    #pc-bg-change{
        background: linear-gradient(to right, #9D34B4, #000000) !important;
    }
    #quickSearch{
        width:70%!important;
    }
    #quickSearch .form-input{
        border-radius: 50px;
       background: #EAEAEA;
    }
    #quickSearch .button{
        background-color:unset !important ;
        border-color: unset !important;
        border:unset !important;
        position: absolute;
        right: 5px; 
        
    }
    #quickSearch .button svg{
        fill: black !important;
    }
}
